import {Banner} from '@primer/react'
import {CopilotIcon} from '@primer/octicons-react'
import type {Sku} from '@github-ui/licensing-common/copilot-types'

import {SummaryCard} from '@github-ui/licensing-common/components/SummaryCard'
import {SummaryCardTwoSectionBody} from '@github-ui/licensing-common/components/SummaryCardTwoSectionBody'
import {CopilotUsageSummary} from '@github-ui/licensing-common/components/CopilotUsageSummary'
import {CopilotPaymentSummary} from '@github-ui/licensing-common/components/CopilotPaymentSummary'
import {SummaryHeaderButtons} from './SummaryHeaderButtons'
import {EnableCTA} from './EnableCTA'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {InlineMessage} from '@primer/react/experimental'
import {useState} from 'react'
import {ProductActivationState} from '@github-ui/licensing-common/types/product-activation-state'

export interface SummaryProps {
  isCopilotEnabled: boolean
  copilotCanBeReenabled: boolean
  canManageCopilot?: boolean
  enablementBlocked: boolean
  businessSlug: string
  copilotTocLink: string
  cfbHelpLink: string
  cfeHelpLink: string
  skus: Sku[]
  billingTermEndDate: string
  totalCost: number
  isTrial: boolean
  ghecTrialExpired?: boolean
  trialExpirationDate?: string
  isDfdTrial: boolean
  isAuthenticatedThroughDfd: boolean
}

export function Summary(props: SummaryProps) {
  const {isStafftools} = useNavigation()
  const [showCsvBanner, setShowCsvBanner] = useState(false)
  const [csvBannerMessage, setCsvBannerMessage] = useState('')
  const [csvBannerTitle, setCsvBannerTitle] = useState<'CSV Export in Progress' | 'CSV Export Error'>(
    'CSV Export in Progress',
  )
  const [csvBannerVariant, setCsvBannerVariant] = useState<'critical' | 'success'>('critical')

  const handleCsvExport = (result: string) => {
    if (result === 'success') {
      setCsvBannerMessage(
        'Your activity report is being generated. You will receive an email when it is ready to download.',
      )
      setCsvBannerTitle('CSV Export in Progress')
      setCsvBannerVariant('success')
    } else {
      setCsvBannerMessage('An error occurred while exporting the CSV report.')
      setCsvBannerTitle('CSV Export Error')
      setCsvBannerVariant('critical')
    }
    setShowCsvBanner(true)
  }

  const [showEnablementError, setShowEnablementError] = useState(false)
  const [enablementErrorMessage, setEnablementErrorMessage] = useState<string>('')
  const handleEnablementError = (show: boolean, message?: string) => {
    setShowEnablementError(show)
    setEnablementErrorMessage(message || '')
  }

  const trialState = props.isDfdTrial
    ? props.ghecTrialExpired
      ? ProductActivationState.TrialExpired
      : ProductActivationState.Trial
    : undefined

  return (
    <>
      {showCsvBanner && (
        <Banner
          title={csvBannerTitle}
          hideTitle
          variant={csvBannerVariant}
          onDismiss={() => setShowCsvBanner(false)}
          className="tmp-mb-3"
          data-testid="csv-download-banner"
        >
          {csvBannerMessage}
        </Banner>
      )}
      {showEnablementError && (
        <Banner
          /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
          title="Copilot Enablement Error"
          hideTitle
          variant="critical"
          onDismiss={() => setShowEnablementError(false)}
          className="tmp-mb-3"
          data-testid="copilot-enablement-error-banner"
        >
          {enablementErrorMessage || 'An error occurred while enabling Copilot for your enterprise account.'}
        </Banner>
      )}
      <SummaryCard
        productActivationState={trialState}
        headerIconComponent={CopilotIcon}
        title="Copilot"
        headerActions={
          trialState !== ProductActivationState.TrialExpired && (
            <SummaryHeaderButtons
              onCsvDownload={handleCsvExport}
              onEnablementError={handleEnablementError}
              isStafftools={isStafftools}
              {...props}
            />
          )
        }
      >
        {props.isCopilotEnabled ? (
          <SummaryCardTwoSectionBody
            primarySection={<CopilotUsageSummary skus={props.skus} headingLevel="h3" />}
            secondarySection={
              <CopilotPaymentSummary
                isTrial={props.isTrial}
                billingTermEndDate={props.billingTermEndDate}
                skus={props.skus}
                totalCost={props.totalCost}
                headingLevel="h3"
              />
            }
            testId="usage-payment-summary"
          />
        ) : isStafftools ? (
          <div className="Box-body" data-testid="stafftools-copilot-disabled">
            Copilot is not enabled on this enterprise.
          </div>
        ) : (
          <EnableCTA {...props} />
        )}
        {props.copilotCanBeReenabled && (
          <InlineMessage size="medium" variant="warning" className="Box-footer tmp-pl-4">
            {'Copilot access has been disabled for the entire enterprise'}
          </InlineMessage>
        )}
        {trialState && props.trialExpirationDate != null && (
          <div className="Box-footer tmp-px-4 f5">
            <span className="color-fg-muted" data-testid="ghas-summary-trial-footer">
              {`Trial ${trialState === ProductActivationState.Trial ? 'ends' : 'ended'} on ${
                props.trialExpirationDate
              }.`}
            </span>
          </div>
        )}
      </SummaryCard>
    </>
  )
}
